import random
for t in range(400):
    n = random.randint(4,30)
    adj = {v:set() for v in range(n)}
    for _ in range(4*n):
        u, v = random.sample(range(n), 2)
        if len(adj[u]) < 3 and len(adj[v]) < 3:
            adj[u].add(v); adj[v].add(u)
    side = [random.randint(0,1) for v in range(n)]
    def phi(): return sum(1 for u in range(n) for v in adj[u] if u < v and side[u]==side[v])
    steps = 0; p0 = phi()
    while True:
        bad = [v for v in range(n) if sum(1 for w in adj[v] if side[w]==side[v]) >= 2]
        if not bad: break
        v = random.choice(bad); before = phi(); side[v] ^= 1; steps += 1
        assert phi() <= before - 1
    assert steps <= p0
    assert all(sum(1 for w in adj[v] if side[w]==side[v]) <= 1 for v in range(n))

