@lru_cache(None)
def win(cols):
    # cols: non-increasing tuple of column heights; poisoned square is (0,0)
    if cols == (1,): return False
    for x in range(len(cols)):
        for y in range(cols[x]):
            if x == 0 and y == 0: continue
            new = tuple(min(c, y) if i >= x else c for i, c in enumerate(cols))
            new = tuple(c for c in new if c > 0)
            if not win(new): return True
    return False
for m in range(1,6):
    for n in range(1,6):
        if m*n > 1: assert win(tuple([m]*n))

