@lru_cache(None)
def win(pos):
    if sum(pos) == 0: return True   # previous player took the last stone and lost
    for i, h in enumerate(pos):
        for k in range(h):
            q = list(pos); q[i] = k
            if not win(tuple(sorted(q))): return True
    return False
for r in (3,4):
    for pos in product(range(6), repeat=r):
        p = tuple(sorted(pos))
        if max(p) <= 1: rule = (sum(p) % 2 == 0)
        else:
            x = 0
            for h in p: x ^= h
            rule = (x != 0)
        assert win(p) == rule

