from itertools import combinations
def trees(n):
    pairs = list(combinations(range(n), 2)); out = []
    for E in combinations(pairs, n-1):
        par = list(range(n))
        def f(a):
            while par[a] != a: a = par[a]
            return a
        ok = True
        for u, v in E:
            a, b = f(u), f(v)
            if a == b: ok = False; break
            par[a] = b
        if ok: out.append(E)
    return out
