def circumference(n, E):
    adj = {v: set() for v in range(n)}
    for u, v in E: adj[u].add(v); adj[v].add(u)
    best = 0
    def dfs(start, v, seen, length):
        nonlocal best
        for w in adj[v]:
            if w == start and length >= 3: best = max(best, length)
            elif w not in seen and w > start:
                seen.add(w); dfs(start, w, seen, length+1); seen.discard(w)
    for s in range(n): dfs(s, s, {s}, 1)
    return best
