def longest_path_edges(n, E):
    adj = {v: set() for v in range(n)}
    for u, v in E: adj[u].add(v); adj[v].add(u)
    best = 0
    def dfs(v, seen, L):
        nonlocal best
        best = max(best, L)
        for w in adj[v]:
            if w not in seen:
                seen.add(w); dfs(w, seen, L+1); seen.discard(w)
    for s in range(n): dfs(s, {s}, 0)
    return best
