for t in range(500):
    n = random.randint(1, 25); p = random.random()
    adj = {v: set() for v in range(n)}
    for u in range(n):
        for v in range(u+1, n):
            if random.random() < p: adj[u].add(v); adj[v].add(u)
    order = random.sample(range(n), n); c = {}
    for v in order:
        used = {c[w] for w in adj[v] if w in c}; k = 0
        while k in used: k += 1
        c[v] = k
    D = max((len(adj[v]) for v in range(n)), default=0)
    assert max(c.values()) + 1 <= D + 1
    rem = set(range(n)); rev = []; d = 0
    while rem:
        v = min(rem, key=lambda x: len(adj[x] & rem)); d = max(d, len(adj[v] & rem))
        rev.append(v); rem.remove(v)
    c = {}
    for v in reversed(rev):
        used = {c[w] for w in adj[v] if w in c}; k = 0
        while k in used: k += 1
        c[v] = k
    assert all(c[u] != c[v] for u in range(n) for v in adj[u])
    assert max(c.values()) + 1 <= d + 1

